const items = $input.all();
const alerts = [];

for (const item of items) {
  const row = item.json;
  const department = row.department || 'Unknown';
  const budget = parseFloat(row.budget || 0);
  const spent = parseFloat(row.spent || 0);
  const percentage = budget > 0 ? Math.round((spent / budget) * 100) : 0;
  const remaining = budget - spent;

  let severity = 'ok';
  if (percentage >= 100) severity = 'over';
  else if (percentage >= 90) severity = 'critical';
  else if (percentage >= 75) severity = 'warning';

  if (severity !== 'ok') {
    alerts.push({
      department,
      budget,
      spent,
      remaining,
      percentage,
      severity,
      date: new Date().toISOString().split('T')[0]
    });
  }
}

if (alerts.length === 0) {
  return [{json: {hasAlerts: false, message: 'All budgets within limits'}}];
}

let alertMsg = ':moneybag: *Daily Budget Alert Report*\n\n';
for (const a of alerts) {
  const icon = a.severity === 'over' ? ':rotating_light:' : a.severity === 'critical' ? ':warning:' : ':eyes:';
  alertMsg += `${icon} *${a.department}*: ${a.percentage}% used ($${a.spent.toLocaleString()} / $${a.budget.toLocaleString()}) — $${a.remaining.toLocaleString()} remaining\n`;
}

return [{json: {
  hasAlerts: true,
  alertMsg,
  alertCount: alerts.length,
  hasCritical: alerts.some(a => a.severity === 'critical' || a.severity === 'over'),
  alerts,
  date: new Date().toISOString().split('T')[0]
}}];
